package com.campusmart.security;
import jakarta.servlet.*;import jakarta.servlet.http.*;import java.io.IOException;import org.springframework.security.authentication.UsernamePasswordAuthenticationToken;import org.springframework.security.core.authority.SimpleGrantedAuthority;import org.springframework.security.core.context.SecurityContextHolder;import org.springframework.stereotype.Component;import org.springframework.web.filter.OncePerRequestFilter;
@Component public class AuthFilter extends OncePerRequestFilter{private final JwtService jwt;public AuthFilter(JwtService jwt){this.jwt=jwt;}protected void doFilterInternal(HttpServletRequest req,HttpServletResponse res,FilterChain chain)throws ServletException,IOException{String h=req.getHeader("Authorization");if(h!=null&&h.startsWith("Bearer ")){try{var c=jwt.verify(h.substring(7));var auth=new UsernamePasswordAuthenticationToken(c.getSubject(),null,java.util.List.of(new SimpleGrantedAuthority("ROLE_"+c.getClaim("role").asString())));SecurityContextHolder.getContext().setAuthentication(auth);}catch(Exception ignored){}}chain.doFilter(req,res);}}
